// [F] DECODIFICADOR: recebe o objeto de bytes lido da CPU (ou do simulador) e gera
// [F] o "instantaneo" com um booleano por bit monitorado. Formato de entrada, igual ao
// [F] do no "s7 in" modo "all variables": msg.payload = { "IB0": 255, "QB8": 3, "MB21": 0, ... }
// [F] msg.origem = "real" | "demo" (definido por cada fonte; a tela mostra em destaque).
// [F] Byte ausente ou nao numerico => o bit fica FORA do instantaneo (a tela mostra "sem dado").
const contrato = global.get("baggio_contrato");
const bytes = msg.payload;
if (!contrato || !bytes || typeof bytes !== "object") { node.warn("payload invalido"); return null; }
const bits = {};
for (const t of contrato.tags) {
  if (!t.bit) continue;                       // so bits (I, Q, M)
  const v = bytes[t.byte];
  if (typeof v !== "number" || v < 0 || v > 255) continue;
  bits[t.endereco] = ((v >> t.nbit) & 1) === 1;
}
global.set("baggio_snap", { ts: Date.now(), origem: msg.origem || "real", bits: bits });
node.status({ fill: "green", shape: "dot", text: Object.keys(bits).length + " bits " + (msg.origem || "real") });
return null;

// [F] Traduz o status do no "s7 in" em estado de comunicacao (so para o diagnostico).
// [F] Verde = conectado e lendo. Qualquer outra cor = sem comunicacao com a CPU.
// [F] A decisao final de "sem comunicacao" tambem usa a IDADE do ultimo instantaneo (API).
const s = msg.status || {};
const ok = s.fill === "green";
global.set("baggio_com", { ok: ok, texto: s.text || "", desde: Date.now() });
return null;

// [F] GET /baggio/api/estado  -> instantaneo atual + saude da comunicacao. SOMENTE LEITURA.
// [F] comunicacao = "ok" so se: existe instantaneo, ele tem menos de LIMITE_MS e o no S7 nao reportou falha.
// [F] Nunca devolve o ultimo valor como se fosse atual: a tela decide pelo campo "comunicacao".
const LIMITE_MS = 5000;
const snap = global.get("baggio_snap");
const com = global.get("baggio_com") || {};
const agora = Date.now();
const idade = snap ? agora - snap.ts : null;
let comunicacao = "ok", motivo = "";
if (!snap) { comunicacao = "sem_comunicacao"; motivo = "sem leitura ainda"; }
else if (idade > LIMITE_MS) { comunicacao = "sem_comunicacao"; motivo = "leitura parada ha " + Math.round(idade/1000) + " s"; }
else if (com.ok === false) { comunicacao = "sem_comunicacao"; motivo = "CPU: " + (com.texto || "desconectada"); }
msg.payload = {
  versao: "0.1", origem: snap ? snap.origem : null, agora: agora,
  ts: snap ? snap.ts : null, idade_ms: idade, comunicacao: comunicacao, motivo: motivo,
  bits: snap ? snap.bits : {}
};
msg.headers = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "Access-Control-Allow-Origin": "*" };
msg.statusCode = 200;
return msg;

// [F] GET /baggio/api/tags -> contrato de tags (so os itens monitorados). SOMENTE LEITURA.
msg.payload = global.get("baggio_contrato");
msg.headers = { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "Access-Control-Allow-Origin": "*" };
msg.statusCode = 200;
return msg;

